-- MediBot demand_factors table
-- Run this in pgAdmin or psql to populate the table

DROP TABLE IF EXISTS demand_factors;
CREATE TABLE demand_factors (
    date DATE PRIMARY KEY,
    day_of_week INTEGER,
    day_name VARCHAR(20),
    month INTEGER,
    year INTEGER,
    week_of_year INTEGER,
    quarter INTEGER,
    is_weekend INTEGER,
    is_holiday INTEGER,
    is_promotion_active INTEGER,
    disease_trend_index FLOAT,
    covid_period_flag INTEGER,
    is_ramadan INTEGER
);

